// --- Helpers ---
const pad = (n) => n.toString().padStart(2, "0");

// --- Robust Date Parser ---
function parseDate(input) {
  if (!input) return new Date();

  const str = input.toString().trim().replace("T", " ");

  let datePart, timePart;

  if (str.includes(" ")) {
    [datePart, timePart] = str.split(" ");
  } else {
    datePart = str;
    timePart = "00:00:00";
  }

  let y, m, d;

  // --- Case 1: MM/DD/YYYY (your input format) ---
  if (datePart.includes("/")) {
    const parts = datePart.split("/").map(Number);

    if (parts.length !== 3) return new Date();

    const [mm, dd, yyyy] = parts;

    if (!mm || !dd || !yyyy) return new Date();

    m = mm;
    d = dd;
    y = yyyy;
  }

  // --- Case 2: YYYY-MM-DD or DD-MM-YYYY ---
  else if (datePart.includes("-")) {
    const parts = datePart.split("-").map(Number);

    if (parts.length !== 3) return new Date();

    if (parts[0] > 31) {
      // YYYY-MM-DD
      [y, m, d] = parts;
    } else {
      // DD-MM-YYYY
      [d, m, y] = parts;
    }
  }

  // --- Unknown format fallback ---
  else {
    return new Date();
  }

  const timeSplit = timePart.split(":").map(Number);
  const hh = timeSplit[0] || 0;
  const min = timeSplit[1] || 0;
  const ss = timeSplit[2] || 0;

  // ✅ LOCAL date (NO timezone shift)
  return new Date(y, m - 1, d, hh, min, ss);
}

// --- Formatter ---
function formatDate(d) {
  if (!(d instanceof Date) || isNaN(d)) {
    return null; // prevent NaN output
  }

  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;
}

// --- Handle Order Deadline ---
let orderDeadline = parseDate(output.Order_Deadline);
const formattedDeadline = formatDate(orderDeadline);

// --- Handle Expected Arrival ---
let expectedArrival = output.Expected_Arrival
  ? parseDate(output.Expected_Arrival)
  : new Date(orderDeadline);

if (!output.Expected_Arrival) {
  expectedArrival.setDate(expectedArrival.getDate() + 7);
}

const formattedArrival = formatDate(expectedArrival);

// --- Validation ---
let reply = null;

if (!formattedDeadline || !formattedArrival) {
  reply = "Error: Invalid date format provided.";
} else {
  const now = new Date();
  const today = new Date(
    now.getFullYear(),
    now.getMonth(),
    now.getDate()
  );

  const deadlineDateOnly = new Date(
    orderDeadline.getFullYear(),
    orderDeadline.getMonth(),
    orderDeadline.getDate()
  );

  if (deadlineDateOnly < today) {
    reply = "Error: Order deadline cannot be in the past.";
  }

  if (expectedArrival <= orderDeadline) {
    reply = "Error: Expected arrival must be after order deadline.";
  }
}

// --- Clean products ---
const cleanedProducts = (output.products || []).map((p) => {
  const product = { ...p };
  if (product.unit_price == null) {
    delete product.unit_price;
  }
  return product;
});

// --- Final Output ---
return [
  {
    json: {
      ...output,
      Order_Deadline: formattedDeadline,
      Expected_Arrival: formattedArrival,
      products: cleanedProducts,
      reply,
    },
  },
];

