const output = items[0].json.output;

// --- Helper: format date to "YYYY-MM-DD HH:mm:ss" ---
const pad = (n) => n.toString().padStart(2, "0");
const formatDateForOdoo = (d) =>
  `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`;

// --- Parse confirmation date ---
const parseDate = (dateStr) => {
  if (!dateStr) return null;

  let d = new Date(dateStr);
  if (isNaN(d.getTime())) {
    const clean = dateStr.replace(/-/g, "/").trim();
    d = new Date(clean);
  }

  return isNaN(d.getTime()) ? null : d;
};

let confirmationDate = output.existing_confirmation_date
  ? parseDate(output.existing_confirmation_date)
  : null;

if (confirmationDate) {
  // ✅ Adjust: decrease one hour to match Odoo API UTC format
  confirmationDate.setHours(confirmationDate.getHours() - 1);
}

let formattedConfirmationDate = confirmationDate
  ? formatDateForOdoo(confirmationDate)
  : null;

// --- Return normalized output ---
return [
  {
    json: {
      ...output,
      existing_confirmation_date: formattedConfirmationDate,
    },
